    stock_num = 0.0
    for index in range(0, len(map_)):
        nodes = map_[str(index)]
        for node in nodes:
            if node['materialCode'] == '4000-G00074' and node['available'] is True:
                print("{level},{nodeId}, {code},{type},{attr},需求量={demand_num},可用={stock_num},在途={in_transit_num},缺料={wait_num}"
                      .format(level=index, nodeId=node['nodeId'], code=node['materialCode'], type=node['materialType'],
                              attr=node['materialAttr'],
                              demand_num=node['demandNum'],
                              stock_num=node['stockNum'], in_transit_num=node['inTransitNum'],
                              wait_num=(node['demandNum'] - node['stockNum'] - node['inTransitNum'])))
                demand_num = demand_num + node['demandNum']
                in_transit_num = in_transit_num + node['inTransitNum']
                stock_num = stock_num + node['stockNum']

    print("需求量= " + str(demand_num))
    print("可用库存= " + str(stock_num))
    print("在途= " + str(in_transit_num))
